import type { EventData } from "@/lib/domain/types";
import { source, SourceError, type DataSource } from "./source";

/**
 * Snapshots are normalized EventData JSON committed under
 * data/snapshots/<slug>/<timestamp>.json. data/snapshots/index.ts maps each
 * slug to its latest file with a lazy import, so a page only bundles its own
 * event. The index is regenerated by `npm run snapshot`.
 */

export type SnapshotLoader = () => Promise<{ default: unknown }>;
export type SnapshotIndex = Record<string, { file: string; load: SnapshotLoader }>;

export function assertEventData(value: unknown, where = "snapshot"): EventData {
  const v = value as Partial<EventData> | null;
  if (!v || typeof v !== "object") throw new SourceError(`${where}: not an object`);
  for (const key of ["registrations", "scores", "schedules"] as const) {
    if (!Array.isArray(v[key])) throw new SourceError(`${where}: missing array "${key}"`);
  }
  if (typeof v.asOf !== "string" || typeof v.source !== "string") throw new SourceError(`${where}: missing asOf/source`);
  return v as EventData;
}

export function snapshotSource(index: SnapshotIndex, slug: string): DataSource<EventData> {
  const entry = index[slug];
  return source(`Snapshot${entry ? ` ${entry.file.replace(/\.json$/, "")}` : ""}`, async () => {
    if (!entry) throw new SourceError(`No snapshot for "${slug}"`);
    const mod = await entry.load();
    return assertEventData(mod.default, `${slug}/${entry.file}`);
  });
}

/** File name for a new snapshot: ISO time with ":" and "." replaced so it is filesystem-safe. */
export function snapshotFileName(date = new Date()): string {
  return `${date.toISOString().replace(/[:.]/g, "-")}.json`;
}

/** Pick the newest snapshot file name (names sort chronologically). */
export function latestSnapshot(files: string[]): string | undefined {
  return files.filter((f) => f.endsWith(".json")).sort().at(-1);
}

export function emptyEventData(sourceLabel: string, asOf = new Date().toISOString()): EventData {
  return { registrations: [], scores: [], schedules: [], asOf, source: sourceLabel };
}

/**
 * Why a fresh scrape must not replace the saved copy, or null if it may
 * (`keep`: share of the saved copy's scored routines the scrape must keep).
 * A source that answers but lost data (cleared sheet, moved columns, an HTML
 * error page) must never wipe the archive.
 */
export function snapshotRegression(prev: EventData | null, next: EventData, keep = 1): string | null {
  if (!next.registrations.length && !next.scores.length) return "the live source returned no entries";
  if (!prev) return null;
  // A 0 typed into a sheet for "didn't compete" is not a score.
  const scored = (d: EventData) => d.scores.filter((s) => s.finalScore != null && s.finalScore > 0).length;
  if (scored(next) < scored(prev) * keep) return `${scored(next)} scored routines vs ${scored(prev)} in the saved copy`;
  return null;
}

/**
 * For pages: a live source counts as broken when it lost most of its scores,
 * or every score of an event that had several (one ring tab cleared or its
 * columns moved). A corrected or removed score is normal. The snapshot
 * script uses the strict check above.
 */
export function liveLostData(saved: EventData, live: EventData): string | null {
  const overall = snapshotRegression(saved, live, 0.5);
  if (overall) return overall;
  const scoredBy = (d: EventData) => {
    const m = new Map<string, number>();
    for (const s of d.scores) if (s.finalScore != null) m.set(s.raw, (m.get(s.raw) ?? 0) + 1);
    return m;
  };
  // Only when the total dropped too: a renamed event keeps its scores under the new name.
  const total = (m: Map<string, number>) => [...m.values()].reduce((a, b) => a + b, 0);
  const was = scoredBy(saved);
  const now = scoredBy(live);
  if (total(now) >= total(was)) return null;
  for (const [raw, n] of was) if (n >= 2 && !now.get(raw)) return `"${raw}" has no scores live (${n} saved)`;
  return null;
}
